// Field adı 'output', 'text' veya başka bir şey olabilir

const aiData = $json;
const webhookData = $('Webhook').item.json;

// AI output'u bul (farklı field adları dene)
let aiOutput = aiData.output || aiData.text || aiData.response || JSON.stringify(aiData);

// String'e çevir
if (typeof aiOutput !== 'string') {
  aiOutput = JSON.stringify(aiOutput);
}

// Debug log (n8n console'da görünür)
console.log('=== AI OUTPUT DEBUG ===');
console.log('AI Output:', aiOutput);
console.log('Contains SEND_PRODUCT_IMAGES:', aiOutput.includes('SEND_PRODUCT_IMAGES'));
console.log('Contains SEND_CATALOG:', aiOutput.includes('SEND_CATALOG'));
console.log('========================');

return {
  json: {
    output: aiOutput,
    webhookData: webhookData
  }
};

// Müşteriye gönderilecek mesajı hazırla (TAG'siz)

const output = $json.output || '';
const webhookData = $json.webhookData;
const recipient = webhookData.body.data.key.remoteJid;

// TAG'leri temizle
let cleanOutput = output
  .replace(/\[SEND_TO_SALES_COORDINATOR\]/g, '')
  .replace(/\[SEND_TO_TECHNICAL_SUPPORT\]/g, '')
  .replace(/\[SEND_COLOR_CARD\]/g, '')
  .replace(/\[SEND_CATALOG\]/g, '')
  .replace(/\[SEND_PRICE_LIST_IMAGE\]/g, '')
  .replace(/\[SEND_PRODUCT_IMAGES:[^\]]+\]/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return {
  json: {
    recipient: recipient,
    messageText: cleanOutput
  }
};

const coordinatorNumber = '905539644020@s.whatsapp.net';
const webhookData = $json.webhookData;
const recipient = webhookData.body.data.key.remoteJid;
const customerNumber = recipient.split('@')[0];
const output = $json.output || '';

const beforeTag = output.split('[SEND_TO_SALES_COORDINATOR]')[0].trim();

// Ürün bilgisini bul
let productInfo = '';
const lines = beforeTag.split('\n').map(l => l.trim()).filter(l => l.length > 0);

// "X adet" pattern'ini ara
for (let line of lines) {
  if (line.match(/\d+ adet/i)) {
    productInfo = line;
    break;
  }
}

if (!productInfo) {
  productInfo = lines.slice(-2).join(' - ');
}

const message = `🔔 YENI SATIS TALEBI\n\n📦 Talep: ${productInfo}\n👤 Musteri: ${customerNumber}\n\n💬 Detay:\n${beforeTag}\n\n⚡ Lutfen en kisa surede muster iyi arayin.`;

return {
  json: {
    recipient: coordinatorNumber,
    message: message
  }
};

